<script setup>import{router,usePage}from'@inertiajs/vue3';import{reactive}from'vue';import AppLayout from'../../Layouts/AppLayout.vue';const props=defineProps({order:Object,filters:Object}),f=reactive({order_number:props.filters?.order_number||'',phone:props.filters?.phone||''}),page=usePage();const money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0);const search=()=>router.get('/track-order',f,{preserveState:true});</script><template><AppLayout><div class="container-shell max-w-3xl py-10"><h1 class="text-3xl font-black">Track your order</h1><p class="mt-2 text-slate-500">Enter the order number and phone number used at checkout.</p><form class="card mt-5 grid gap-3 p-4 sm:grid-cols-[1fr_1fr_auto]" @submit.prevent="search"><input v-model="f.order_number" class="input" placeholder="Order number"><input v-model="f.phone" class="input" placeholder="Phone number"><button class="btn-primary">Track</button></form><div v-if="order" class="card mt-6 p-5"><div class="flex flex-wrap justify-between gap-3"><div><p class="text-xs font-black uppercase text-prinx-600">{{order.order_number}}</p><h2 class="mt-1 text-xl font-black capitalize">{{order.status}}</h2></div><b>{{money(order.grand_total)}}</b></div><div class="mt-5"><h3 class="font-black">Progress</h3><div class="mt-3 space-y-3"><div v-for="h in order.status_history" :key="h.id" class="border-l-2 border-prinx-400 pl-4"><p class="font-bold capitalize">{{h.status}}</p><p class="text-xs text-slate-500">{{new Date(h.created_at).toLocaleString()}} · {{h.note||h.payment_status}}</p></div></div></div></div></div></AppLayout></template>
